class OrderServiceConstructorInjection {
    private final Notifier notifier; // MOZE byc final

    OrderServiceConstructorInjection(Notifier notifier) {
        this.notifier = notifier; // zaleznosc WIDOCZNA wprost w konstruktorze
    }

    void placeOrder(String item) {
        notifier.notify("Zamowiono: " + item); // zawsze bezpieczne - notifier NIGDY nie jest null
    }
}

class OrderServiceSetterInjection {
    private Notifier notifier; // NIE moze byc final - ustawiane PO konstrukcji

    void setNotifier(Notifier notifier) { this.notifier = notifier; }

    void placeOrder(String item) {
        if (notifier != null) notifier.notify("Zamowiono: " + item); // opcjonalna zaleznosc
    }
}

